import itertools

def time_to_min(text):
    text = text.strip().upper()
    if text.endswith("AM"):
        period = "AM"
        body = text[:-2]
    else:
        period = "PM"
        body = text[:-2]
    hour, minute = map(int, body.split(":"))
    if period == "AM":
        if hour == 12:
            hour = 0
    else:
        if hour != 12:
            hour += 12
    return hour * 60 + minute

